B.Xx=new A.cL([1,"Ch\xfang t\xf4i ghi nh\u1eadn b\u1ea1n \u0111\xe3 2 ng\xe0y ch\u01b0a \u0111\u1ed3ng b\u1ed9 d\u1eef li\u1ec7u m\u1edbi. Y\xeau c\u1ea7u b\u1ea1n h\u1ee3p t\xe1c th\u1ef1c hi\u1ec7n \u0111\u1ed3ng b\u1ed9 \u0111\u1ec3 b\u1ea3o \u0111\u1ea3m t\xednh ch\xednh x\xe1c c\u1ee7a d\u1eef li\u1ec7u.",2,"\u0110\u1ed3ng b\u1ed9 ho\xe0n t\u1ea5t. Kh\xf4ng ghi nh\u1eadn thay \u0111\u1ed5i m\u1edbi trong d\u1eef li\u1ec7u l\u1ecbch h\u1ecdc ho\u1eb7c l\u1ecbch thi.",3,"H\u1ec7 th\u1ed1ng ghi nh\u1eadn thay \u0111\u1ed5i trong l\u1ecbch h\u1ecdc. Y\xeau c\u1ea7u b\u1ea1n ki\u1ec3m tra l\u1ea1i th\xf4ng tin tr\u01b0\u1edbc khi \u0111\u1ebfn l\u1edbp.",4,"H\u1ec7 th\u1ed1ng ghi nh\u1eadn thay \u0111\u1ed5i trong l\u1ecbch thi. Y\xeau c\u1ea7u b\u1ea1n ki\u1ec3m tra l\u1ea1i th\xf4ng tin \u0111\u1ec3 b\u1ea3o \u0111\u1ea3m tham gia \u0111\xfang ca thi.",5,"H\u1ec7 th\u1ed1ng ghi nh\u1eadn thay \u0111\u1ed5i \u0111\u1ed3ng th\u1eddi trong l\u1ecbch h\u1ecdc v\xe0 l\u1ecbch thi. Y\xeau c\u1ea7u b\u1ea1n ki\u1ec3m tra l\u1ea1i to\xe0n b\u1ed9 th\xf4ng tin li\xean quan.",6,"C\xf2n 7 ng\xe0y tr\u01b0\u1edbc k\u1ef3 thi. Vui l\xf2ng ki\u1ec3m tra l\u1ecbch.",7,"C\xf2n 3 ng\xe0y tr\u01b0\u1edbc k\u1ef3 thi. Vui l\xf2ng ki\u1ec3m tra l\u1ea1i l\u1ecbch.",8,"Ng\xe0y mai l\xe0 ng\xe0y thi. Vui l\xf2ng ki\u1ec3m tra l\u1ea1i l\u1ecbch.",9,"C\xf2n X ng\xe0y tr\u01b0\u1edbc k\u1ef3 thi. Vui l\xf2ng r\xe0 so\xe1t l\u1ea1i l\u1ecbch.",10,"B\u1ea1n \u0111ang trong k\u1ef3 thi. Vui l\xf2ng theo d\xf5i l\u1ecbch thi th\u01b0\u1eddng xuy\xean.",11,"C\xf2n X ng\xe0y, b\u1ea1n c\xf3 N m\xf4n thi. Vui l\xf2ng r\xe0 so\xe1t l\u1ecbch.",12,"\u0110\u1ed3ng b\u1ed9 ho\xe0n t\u1ea5t. H\u1ec7 th\u1ed1ng ghi nh\u1eadn thay \u0111\u1ed5i trong d\u1eef li\u1ec7u.",13,"\u0110\u1ed3ng b\u1ed9 ho\xe0n t\u1ea5t. Kh\xf4ng ghi nh\u1eadn thay \u0111\u1ed5i m\u1edbi.",14,"H\u1ec7 th\u1ed1ng ghi nh\u1eadn thay \u0111\u1ed5i. Vui l\xf2ng m\u1edf chi ti\u1ebft \u0111\u1ec3 ki\u1ec3m tra.",15,"Hi\u1ec7n ch\u01b0a ghi nh\u1eadn l\u1ecbch thi trong d\u1eef li\u1ec7u c\u1ee7a b\u1ea1n.",16,"H\xf4m nay kh\xf4ng ghi nh\u1eadn l\u1ecbch h\u1ecdc.",17,"\u0110\u1ed3ng b\u1ed9 kh\xf4ng ho\xe0n t\u1ea5t. Vui l\xf2ng th\u1ef1c hi\u1ec7n l\u1ea1i.",18,"Qu\xe1 tr\xecnh \u0111\u1ed3ng b\u1ed9 \u0111\xe3 v\u01b0\u1ee3t th\u1eddi gian ch\u1edd. Vui l\xf2ng th\u1eed l\u1ea1i."],t.TM)
B.Xu=new A.cL([1,"Fen \u01a1i, 2 ng\xe0y r\u1ed3i \u0111\u1ea5y! C\u1eadp nh\u1eadt d\u1eef li\u1ec7u m\u1edbi \u0111i ch\u1ee9 fen!",2,"Xong r\u1ed3i fen! L\u1ecbch v\u1eabn y nguy\xean, ch\u01b0a c\xf3 g\xec m\u1edbi h\u1ebft \xe1.",3,"Fen \u01a1i, l\u1ecbch h\u1ecdc \u0111\u1ed5i r\u1ed3i k\xeca! V\xe0o xem l\u1ea1i l\u1eb9 \u0111i.",4,"Fen \u01a1i, l\u1ecbch thi \u0111\u1ed5i r\u1ed3i k\xeca! V\xe0o check l\u1ea1i l\u1eb9 nha.",5,"Fen \u01a1i, c\u1ea3 l\u1ecbch h\u1ecdc l\u1eabn l\u1ecbch thi \u0111\u1ec1u \u0111\u1ed5i r\u1ed3i k\xeca! V\xe0o check nhanh \u0111i fen!",6,"Fen \u01a1i, 7 ng\xe0y n\u1eefa thi r\u1ed3i \u0111\xf3!",7,"Fen \u01a1i, c\xf2n 3 ng\xe0y n\u1eefa thi th\xf4i \u0111\xf3!",8,"Fen \u01a1i, mai thi r\u1ed3i \u0111\xf3!",9,"Fen \u01a1i, c\xf2n X ng\xe0y n\u1eefa thi \u0111\xf3!",10,"Fen \u0111ang trong k\u1ef3 thi \u0111\xf3 nha, nh\u1edb check l\u1ecbch!",11,"Fen \u01a1i, X ng\xe0y n\u1eefa c\xf3 t\u1eadn N m\xf4n thi \u0111\xf3!",12,"Fen \u01a1i, sync xong c\xf3 l\u1ecbch m\u1edbi n\xe8!",13,"Xong r\u1ed3i fen! V\u1eabn y nguy\xean nha.",14,"Fen \u01a1i, c\xf3 thay \u0111\u1ed5i n\xe8! V\xe0o xem chi ti\u1ebft \u0111i.",15,"Fen \u01a1i, ch\u01b0a c\xf3 l\u1ecbch thi nha!",16,"Fen \u01a1i, nay \u0111\u01b0\u1ee3c ngh\u1ec9!",17,"Fen \u01a1i, sync h\u1ee5t m\u1ea5t r\u1ed3i! Th\u1eed l\u1ea1i nha.",18,"Fen \u01a1i, ch\u1edd l\xe2u qu\xe1 r\u1ed3i! Th\u1eed sync l\u1ea1i nha."],t.TM)
B.Xt=new A.cL([1,"L\xe2u r\u1ed3i m\xecnh ch\u01b0a th\u1ea5y c\u1eadu \u0111\u1ed3ng b\u1ed9 \xed... \u0111\u1ec3 \xfd m\xecnh ch\xfat nha!",2,"M\xecnh ki\u1ec3m tra xong r\u1ed3i n\xe8, l\u1ecbch v\u1eabn nh\u01b0 c\u0169 th\xf4i... ch\u01b0a c\xf3 g\xec m\u1edbi \u0111\xe2u.",3,"M\xecnh th\u1ea5y l\u1ecbch h\u1ecdc b\u1ea1n c\xf3 thay \u0111\u1ed5i, b\u1ea1n ki\u1ec3m tra nhaaa.",4,"M\xecnh th\u1ea5y l\u1ecbch thi c\u1ee7a b\u1ea1n c\xf3 thay \u0111\u1ed5i, b\u1ea1n xem l\u1ea1i nhaaa.",5,"M\xecnh th\u1ea5y c\u1ea3 l\u1ecbch h\u1ecdc v\u1edbi l\u1ecbch thi c\u1ee7a b\u1ea1n \u0111\u1ec1u c\xf3 thay \u0111\u1ed5i, b\u1ea1n ki\u1ec3m tra nhaaa.",6,"C\xf2n 7 ng\xe0y n\u1eefa thi r\u1ed3i, b\u1ea1n nh\u1edb chu\u1ea9n b\u1ecb nha.",7,"C\xf2n 3 ng\xe0y n\u1eefa thi r\u1ed3i, b\u1ea1n nh\u1edb gi\u1eef s\u1ee9c nha.",8,"Mai thi r\u1ed3i, b\u1ea1n ng\u1ee7 s\u1edbm nha.",9,"C\xf2n X ng\xe0y n\u1eefa thi r\u1ed3i, b\u1ea1n chu\u1ea9n b\u1ecb d\u1ea7n nha.",10,"B\u1ea1n \u0111ang trong k\u1ef3 thi r\u1ed3i, nh\u1edb gi\u1eef s\u1ee9c v\xe0 xem l\u1ecbch nha.",11,"X ng\xe0y n\u1eefa b\u1ea1n c\xf3 N m\xf4n thi r\u1ed3i, nh\u1edb chu\u1ea9n b\u1ecb nha.",12,"M\xecnh sync xong r\u1ed3i, l\u1ecbch c\u1ee7a b\u1ea1n c\xf3 thay \u0111\u1ed5i nha.",13,"M\xecnh ki\u1ec3m tra xong r\u1ed3i, ch\u01b0a c\xf3 g\xec thay \u0111\u1ed5i \u0111\xe2u nha.",14,"M\xecnh th\u1ea5y c\xf3 thay \u0111\u1ed5i \u0111\xf3, b\u1ea1n m\u1edf xem th\u1eed nha.",15,"M\xecnh ch\u01b0a th\u1ea5y l\u1ecbch thi c\u1ee7a b\u1ea1n \u0111\xe2u, y\xean t\xe2m nha.",16,"H\xf4m nay \u0111\u01b0\u1ee3c ngh\u1ec9 r\u1ed3i, th\u01b0 gi\xe3n ch\xfat nha.",17,"M\xecnh ch\u01b0a \u0111\u1ed3ng b\u1ed9 \u0111\u01b0\u1ee3c cho b\u1ea1n r\u1ed3i... th\u1eed l\u1ea1i gi\xfap m\xecnh nha.",18,"M\xecnh ch\u1edd m\xe3i m\xe0 ch\u01b0a l\u1ea5y \u0111\u01b0\u1ee3c d\u1eef li\u1ec7u... th\u1eed l\u1ea1i ch\xfat nha."],t.TM)
B.Xs=new A.cL([1,"Bi\u1ebft l\xe0 b\u1eadn r\u1ed3i? Nh\u01b0ng m\xe0 ng\u01b0\u1eddi ta c\u0169ng c\u1ea7n ph\u1ea3i sync m\xe0!",2,"Sync xong r\u1ed3i n\xe8, v\u1eabn nh\u01b0 c\u0169 nha \u2764\ufe0f",3,"C\xf3 g\xec \u0111\xf3 gi\u1eefa ch\xfang ta \u0111\xe3 thay \u0111\u1ed5i \u1ea5y, ki\u1ec3m tra l\u1ecbch h\u1ecdc nha \u2764\ufe0f",4,"M\xecnh c\xf2n m\u1eadp m\u1edd nh\u01b0ng l\u1ecbch thi th\xec \u0111\u1ed5i r\xf5 \u2764\ufe0f B\u1ea1n ki\u1ec3m tra nha.",5,"M\xecnh v\xe0 b\u1ea1n r\u1ed3i ai c\u0169ng thay \u0111\u1ed5i, c\u1ea3 l\u1ecbch h\u1ecdc v\xe0 l\u1ecbch thi c\u0169ng v\u1eady! \u2764\ufe0f",6,"7 ng\xe0y n\u1eefa thi r\u1ed3i \u0111\xf3... h\u1ecdc \u0111i nha \u2764\ufe0f",7,"3 ng\xe0y n\u1eefa thi r\u1ed3i... h\u1ecdc \u0111i, \u0111\u1eebng \u0111\u1ec3 m\xecnh ph\u1ea3i lo \u2764\ufe0f",8,"Mai thi r\u1ed3i \u0111\xf3... t\u1ed1i nay ngoan ngo\xe3n h\u1ecdc b\xe0i nha \u2764\ufe0f",9,"C\xf2n X ng\xe0y n\u1eefa thi th\xf4i... nh\u1edb \u0111\u1ec3 \xfd l\u1ecbch, v\u1edbi \u0111\u1ec3 \xfd m\xecnh n\u1eefa nha \u2764\ufe0f",10,"Nh\u1edb m\xecnh th\xec nh\u1edb, nh\u01b0ng nh\u1edb c\u1ea3 l\u1ecbch thi n\u1eefa nha \u2764\ufe0f",11,"Ch\u1eafc g\xec nh\u1edb m\u1ed7i ng\u01b0\u1eddi ta... v\u1eady m\xe0 m\xecnh nh\u1edb ng\u01b0\u1eddi ta c\xf2n X ng\xe0y n\u1eefa c\xf3 N m\xf4n thi \u0111\xf3 \u2764\ufe0f",12,"L\u1ecbch c\u1ee7a ch\xfang m\xecnh v\u1eeba \u0111\u1ed5i r\u1ed3i \u1ea5y \u2764\ufe0f",13,"Ch\xfang m\xecnh v\u1eabn nh\u01b0 c\u0169 nha \u2764\ufe0f",14,"C\xf3 m\u1ed9t thay \u0111\u1ed5i m\xecnh ch\u01b0a k\u1ec3 b\u1ea1n n\xe8 \u2764\ufe0f M\u1edf xem \u0111i.",15,"L\u1ecbch thi th\xec ch\u01b0a c\xf3... c\xf2n l\u1ecbch v\u1edbi m\xecnh th\xec sao? \u2764\ufe0f",16,"Nay kh\xf4ng h\u1ecdc... M\xecnh mu\u1ed1n \u0111i ch\u01a1i! \u2764\ufe0f",17,"H\u1ecfng r\u1ed3i! Ch\xfang m\xecnh l\xe0m l\u1ea1i nha \u2764\ufe0f",18,"\u0110\u1ee3i m\xecnh th\xec \u0111\u01b0\u1ee3c \u2764\ufe0f ch\u1ee9 \u0111\u1ed1ng d\u1eef li\u1ec7u n\xe0y th\xec sync l\u1ea1i th\xf4i."],t.TM)
B.Xw=new A.cL([1,"\u0110\xe3 v\u01b0\u1ee3t qu\xe1 kho\u1ea3ng th\u1eddi gian khuy\u1ebfn ngh\u1ecb gi\u1eefa hai l\u1ea7n \u0111\u1ed3ng b\u1ed9. T\xf4i \u0111\u1ec1 ngh\u1ecb b\u1ea1n c\u1eadp nh\u1eadt d\u1eef li\u1ec7u \u0111\u1ec3 gi\u1ea3m nguy c\u01a1 sai l\u1ec7ch so v\u1edbi h\u1ec7 th\u1ed1ng QL\u0110T.",2,"Qu\xe1 tr\xecnh \u0111\u1ed3ng b\u1ed9 \u0111\xe3 ho\xe0n t\u1ea5t. D\u1eef li\u1ec7u hi\u1ec7n t\u1ea1i kh\xf4ng c\xf3 sai kh\xe1c so v\u1edbi l\u1ea7n \u0111\u1ed3ng b\u1ed9 th\xe0nh c\xf4ng g\u1ea7n nh\u1ea5t.",3,"Ph\xe1t hi\u1ec7n sai kh\xe1c trong d\u1eef li\u1ec7u l\u1ecbch h\u1ecdc so v\u1edbi l\u1ea7n \u0111\u1ed3ng b\u1ed9 g\u1ea7n nh\u1ea5t. Vui l\xf2ng ki\u1ec3m tra chi ti\u1ebft thay \u0111\u1ed5i.",4,"Ph\xe1t hi\u1ec7n sai kh\xe1c trong d\u1eef li\u1ec7u l\u1ecbch thi so v\u1edbi l\u1ea7n \u0111\u1ed3ng b\u1ed9 g\u1ea7n nh\u1ea5t. Vui l\xf2ng ki\u1ec3m tra chi ti\u1ebft thay \u0111\u1ed5i.",5,"Ph\xe1t hi\u1ec7n sai kh\xe1c \u0111\u1ed3ng th\u1eddi trong d\u1eef li\u1ec7u l\u1ecbch h\u1ecdc v\xe0 l\u1ecbch thi so v\u1edbi l\u1ea7n \u0111\u1ed3ng b\u1ed9 g\u1ea7n nh\u1ea5t. Vui l\xf2ng ki\u1ec3m tra chi ti\u1ebft c\xe1c thay \u0111\u1ed5i.",6,"K\u1ef3 thi c\xf2n 7 ng\xe0y. H\xe3y r\xe0 so\xe1t l\u1ecbch thi.",7,"K\u1ef3 thi c\xf2n 3 ng\xe0y. H\xe3y r\xe0 so\xe1t l\u1ecbch v\xe0 chu\u1ea9n b\u1ecb.",8,"K\u1ef3 thi di\u1ec5n ra v\xe0o ng\xe0y mai. H\xe3y r\xe0 so\xe1t l\u1ecbch thi.",9,"K\u1ef3 thi c\xf2n X ng\xe0y. H\xe3y ki\u1ec3m tra l\u1ecbch v\xe0 \u0111i\u1ec1u ch\u1ec9nh k\u1ebf ho\u1ea1ch \xf4n t\u1eadp.",10,"B\u1ea1n \u0111ang trong giai \u0111o\u1ea1n thi. H\xe3y th\u01b0\u1eddng xuy\xean r\xe0 so\xe1t l\u1ecbch thi.",11,"Trong X ng\xe0y t\u1edbi c\xf3 N m\xf4n thi. H\xe3y ph\xe2n b\u1ed5 th\u1eddi gian \xf4n t\u1eadp ph\xf9 h\u1ee3p.",12,"\u0110\u1ed3ng b\u1ed9 ho\xe0n t\u1ea5t v\xe0 ph\xe1t hi\u1ec7n sai kh\xe1c so v\u1edbi d\u1eef li\u1ec7u tr\u01b0\u1edbc \u0111\xf3.",13,"\u0110\u1ed3ng b\u1ed9 ho\xe0n t\u1ea5t. Kh\xf4ng ph\xe1t hi\u1ec7n sai kh\xe1c so v\u1edbi d\u1eef li\u1ec7u tr\u01b0\u1edbc \u0111\xf3.",14,"Ph\xe1t hi\u1ec7n sai kh\xe1c trong d\u1eef li\u1ec7u. Vui l\xf2ng ki\u1ec3m tra ph\u1ea7n chi ti\u1ebft.",15,"D\u1eef li\u1ec7u hi\u1ec7n t\u1ea1i ch\u01b0a ghi nh\u1eadn ca thi n\xe0o.",16,"D\u1eef li\u1ec7u hi\u1ec7n t\u1ea1i kh\xf4ng ghi nh\u1eadn bu\u1ed5i h\u1ecdc n\xe0o trong h\xf4m nay.",17,"Qu\xe1 tr\xecnh \u0111\u1ed3ng b\u1ed9 kh\xf4ng ho\xe0n t\u1ea5t. Vui l\xf2ng th\u1ef1c hi\u1ec7n l\u1ea1i \u0111\u1ec3 c\u1eadp nh\u1eadt d\u1eef li\u1ec7u.",18,"Y\xeau c\u1ea7u \u0111\u1ed3ng b\u1ed9 \u0111\xe3 v\u01b0\u1ee3t ng\u01b0\u1ee1ng th\u1eddi gian ch\u1edd. Vui l\xf2ng th\u1ef1c hi\u1ec7n l\u1ea1i."],t.TM)
B.Xr=new A.cL([1,"C\xf3 m\u1ed7i c\xe1i vi\u1ec7c sync m\xe0 m\xe0y c\u0169ng l\u01b0\u1eddi? Mai \u0111i h\u1ecdc mu\u1ed9n \u0111\u1eebng \u0111\u1ed5 t\u1ea1i tao nh\xe9.",2,"Tao sync xong r\u1ed3i \u0111\u1ea5y, m\xe0y ch\u1ea3 \u0111\u01b0\u1ee3c ngh\u1ec9 bu\u1ed5i n\xe0o.",3,"L\u1ecbch h\u1ecdc \u0111\u1ed5i r\u1ed3i \u0111\u1ea5y, c\xf2n kh\xf4ng mau check \u0111i?",4,"L\u1ecbch thi \u0111\u1ed5i r\u1ed3i \u0111\u1ea5y. Kh\xf4ng check th\xec tr\u01b0\u1ee3t r\xe1ng ch\u1ecbu.",5,"M\xe0y l\xe0m g\xec m\xe0 ng\u01b0\u1eddi ta \u0111\u1ed5i c\u1ea3 l\u1ecbch h\u1ecdc l\u1eabn l\u1ecbch thi c\u1ee7a m\xe0y r\u1ed3i k\xeca.",6,"7 ng\xe0y n\u1eefa thi r\u1ed3i m\xe0 m\xe0y ch\u01b0a ch\u1ecbu h\u1ecdc \xe0?",7,"3 ng\xe0y n\u1eefa thi m\xe0 gi\u1edd v\u1eabn ng\u1ed3i l\u01b0\u1edbt?",8,"N\xf3i kh\xf4ng nghe!? Mai thi gi\u1edd l\u1ea1i c\u1eafm \u0111\u1ea7u \xf4n.",9,"C\xf2n X ng\xe0y n\u1eefa thi, gi\u1edd m\u1edbi nh\u1edb t\u1edbi \xe0?",10,"\u0110ang trong k\u1ef3 thi \u0111\u1ea5y, qu\xean l\u1ecbch th\xec t\u1ef1 \u0111i m\xe0 g\xe1nh.",11,"C\xf2n X ng\xe0y n\u1eefa m\xe0y c\xf3 N m\xf4n thi \u0111\u1ea5y, ch\u01a1i \xedt th\xf4i!",12,"L\u1ecbch \u0111\u1ed5i r\u1ed3i \u0111\u1ea5y, v\xe0o xem \u0111i? L\u1ea1y B\u1ed1\u1ed1\u1ed1!",13,"Sync xong r\u1ed3i \u0111\u1ea5y, v\u1eabn ch\u1ea3 \u0111\u01b0\u1ee3c ngh\u1ec9.",14,"V\xe0o xem c\xf3 g\xec \u0111\u1ed5i chi ti\u1ebft k\xeca? \u0110\u1ee3i tao \u0111\u1ecdc cho nghe \xe0?",15,"Qu\u1ea9y \u0111\xea, n\xe0o c\xf3 l\u1ecbch tao b\xe1o.",16,"M\xe3i m\u1edbi \u0111\u01b0\u1ee3c ngh\u1ec9 1 h\xf4m.",17,"C\xf3 m\u1ed7i c\xe1i sync m\xe0 m\xe0y c\u0169ng l\u1ed7i? L\xe0m l\u1ea1i \u0111\xea!",18,"M\xe0y \u0111\u1ecbnh ch\u1edd bao l\xe2u n\u1eefa? Kh\xf4ng bi\u1ebft \u0111\u01b0\u1eddng m\xe0 sync l\u1ea1i \xe0?"],t.TM)
B.Xv=new A.cL([1,"Ph\xe1p tr\u1eadn l\xe2u ng\xe0y ch\u01b0a \u0111\u01b0\u1ee3c v\u1eadn, truy\u1ec1n t\u1ed1ng t\u1eafc ngh\u1ebdn. Mau \u0111\u1ed3ng b\u1ed9 k\u1ebbo tu h\xe0nh g\u1eb7p sai s\xf3t.",2,"Ph\xe1p tr\u1eadn khai th\xf4ng, truy\u1ec1n t\u1ed1ng kh\xf4ng c\xf3 sai s\xf3t. Thi\xean \u0111\u1ea1o b\u1ea5t bi\u1ebfn \u2014 an t\xe2m tu h\xe0nh.",3,"Thi\xean c\u01a1 \u0111\u1ea1i bi\u1ebfn, d\u1ec5 sinh d\u1ecb t\u01b0\u1ee3ng. C\xf2n kh\xf4ng mau ki\u1ec3m tra?",4,"B\xed c\u1ea3nh m\u1edbi xu\u1ea5t hi\u1ec7n, th\xed luy\u1ec7n \u1eaft bi\u1ebfn. Mau ki\u1ec3m tra l\u1ea1i!",5,"Thi\xean c\u01a1 h\u1ed7n lo\u1ea1n, b\xed c\u1ea3nh \u0111\u1ea1i bi\u1ebfn. C\xf2n kh\xf4ng mau r\xe0 so\xe1t?",6,"7 ng\xe0y n\u1eefa, thi\xean ki\u1ebfp gi\xe1ng l\xe2m. Tr\u1eddi sinh d\u1ecb bi\u1ebfn \u2014 mau chu\u1ea9n b\u1ecb \u0111\u1ed9 ki\u1ebfp.",7,"3 ng\xe0y sau, thi\xean ki\u1ebfp \u0111\xe3 c\u1eadn k\u1ec1. L\xf4i v\xe2n t\xedch t\u1ee5 \u2014 c\xf2n kh\xf4ng mau b\u1ebf quan?",8,"Thi\xean ki\u1ebfp gi\xe1ng l\xe2m. Gi\u1eef v\u1eefng \u0111\u1ea1o t\xe2m \u2014 ch\xfac ng\u01b0\u01a1i may m\u1eafn!",9,"X ng\xe0y sau, tu vi vi\xean m\xe3n. L\xf4i ki\u1ebfp gi\xe1ng l\xe2m \u2014 h\xe3y chu\u1ea9n b\u1ecb th\u1eadt t\u1ed1t!",10,"\u0110\xe3 t\u1edbi k\u1ef3 \u0111\u1ed9 ki\u1ebfp, Thi\xean \u0111\u1ea1o kh\u1ea3o h\u1ea1ch. D\u1ecb \u0111\u1ed9ng l\u01b0u t\xe2m \u2014 \u0111\u1ea1o n\xe0y \u0111i sai, v\u1ea1n ki\u1ebfp b\u1ea5t ph\u1ee5c.",11,"C\xf2n X ng\xe0y, N \u0111\u1ea1o thi\xean ki\u1ebfp c\xf9ng l\xfac gi\xe1ng xu\u1ed1ng. Tu vi c\xf3 h\u1ea1n \u2014 ch\u1edb c\xf3 l\u01a1 l\xe0!",12,"Ph\xe1p tr\u1eadn khai th\xf4ng, truy\u1ec1n t\u1ed1ng sinh bi\u1ebfn. Thi\xean c\u01a1 ngh\u1ecbch v\u1eadn \u2014 mau ki\u1ec3m tra.",13,"Ph\xe1p tr\u1eadn v\u1eeba khai th\xf4ng, truy\u1ec1n t\u1ed1ng kh\xf4ng c\xf3 sai s\xf3t. Thi\xean \u0111\u1ea1o b\u1ea5t bi\u1ebfn \u2014 an t\xe2m tu h\xe0nh.",14,"Thi\xean c\u01a1 kh\u1ebd \u0111\u1ed9ng, b\xed c\u1ea3nh \u1eaft bi\u1ebfn. Mau m\u1edf chi ti\u1ebft ki\u1ec3m tra.",15,"B\xed c\u1ea3nh ch\u01b0a m\u1edf, ch\u1edb v\u1ed9i kh\u1ea3o h\u1ea1ch. H\xe3y chu\u1ea9n b\u1ecb th\u1eadt t\u1ed1t!",16,"Nay v\xf4 bi\u1ebfn v\xf4 m\u01b0u, an t\xe2m t\u0129nh d\u01b0\u1ee1ng.",17,"Ph\xe1p tr\u1eadn ph\u1ea3n ph\u1ec7, truy\u1ec1n t\u1ed1ng kh\xf4ng th\xe0nh. C\xf2n kh\xf4ng mau th\u1eed l\u1ea1i?",18,"Ph\xe1p tr\u1eadn \u0111\xecnh tr\u1ec7, thi\xean \u0111\u1ea1o kh\xf3 dung. Ch\u1edb c\u01b0\u1ee1ng c\u1ea7u \u2014 h\xe3y quay l\u1ea1i sau."],t.TM)
